  "A filter highlights items based on type and value (based on current inGame economy), and hides bad ones.": "过滤器会按类型与价值（基于当前游戏内经济）高亮物品，并隐藏不值钱的物品。",
  "A Gemcutter's Prism is acquired by selling a gem with 20% quality or gems with a combined total of 40% quality to a vendor.": "宝石匠的棱镜可以通过向商人出售品质为20%的宝石或品质总和为40%的多个宝石来获得。",
  "A little birdy said these may drop from mirage...": "有小道消息说这些可能从幻象中掉落……",
