  "A potentially expensive unique version of this item drops ONLY from bosses! The world drop unique is fairly cheap! You can hide this tier, BUT remember to check the hidden items dropped by bosses!": "此物品潜在昂贵的传奇版本只从首领掉落！世界掉落的传奇相当便宜！你可以隐藏此层级，但记住检查首领掉落的隐藏物品！",
