  "All or most items in this section are tiered based on the current economy (PoE.Ninja). This section is updated every 4 hours (except on the 'SSF' filter).": "本节中全部或大部分物品按当前经济行情（PoE.Ninja）分级。本节每 4 小时更新一次（「SSF」过滤器除外）。",
  "All or most items in this section are tiered based on the current economy (PoE.Ninja). This section is updated every 4 hours (except on the 'Stable' filter).": "该部分的所有或大多数物品都是基于当前经济而分阶的。这部分每4小时更新一次(除了“稳定版”过滤器)。",
  "All other Mirage drops are part of the 'standard' tierlists. For instance all currency drops, astrolabes and coins are part of the currency tierlist.": "所有其他幻象掉落都属于'标准'分层列表。例如所有通货掉落、星盘和硬币都属于通货分层列表。",
  "All red-green-blue linked items sell for exactly one Chromatic Orb. It's more efficient to pick up smaller RGB-items for this recipe.": "所有红绿蓝连物品恰好卖一个 chromat orb。对于这个配方，拾取较小的 RGB 物品更有效率。",
  "All top tier items have the same white background and drop-sound. They also come with a red beam and a huge red star on the minimap. These items include top tier currencies, valuable uniques, great divination cards, reliquary keys and everything else that is worth a LOT.": "所有顶级物品都有相同的白色背景和掉落声音。它们还会在小地图上出现红色光束和一颗巨大红星。这些物品包括顶级通货、珍贵的传奇物品、伟大的命运卡、圣物钥匙以及其他一切昂贵的物品。",
