  "ANIMATE WEAPON: This section should only interest Animate Weapon skill-gem users. Please note that if you use Cloak/Transfigured AW Gems, you'll have to activate multiple entries below, not only one. This entry has a lower priority than crafting, chancing, and other valuable normal/magic weapons.": "幻化武器：此部分仅对使用幻化武器技能宝石的玩家有用。请注意，如果你使用斗篷/转化幻化武器宝石，你需要激活下方多个条目，而非仅一个。此条目的优先级低于工艺、点装和其他有价值的普通/魔法武器。",
