  "Anointed Rings": "涂油戒指",
  "Another important detail is that you can only chance non-drop-restricted uniques. Boss-drops and exclusive drops can't be chanced. The top section represents 'somewhat' realistic chancing targets. The bottom section is basically a lottery. You need thousands of chancing orbs to hit one of the expensive uniques here.": "另一个重要的细节是你只能选择不受掉落限制的传奇进行机会是石的尝试。boss掉落和专属掉落是不可能的。上面的部分代表“有点”现实的机会石目标。底部的部分基本上是抽签。你需要成千上万的机会石来抽中这里的某个昂贵的传奇物品。",
