  "any": "任意",
  "Any changes done on the site will affect all other screens (such as loot simulator). You can switch back and forth until you're satisfied with your filter. This customizer is built to be fail-proof and is designed to prevent causing damage to your filter.": "在此页面上所做的任何更改将影响所有其他页面(如战利品模拟器)。你可以来回切换，直到你满意你的过滤器。此定制器是用于防止故障的，旨在防止对您的过滤器造成损坏。",
  "Any Enchantment": "任意附魔",
  "Any Imbued Drop": "任何灌注掉落",
  "Any item copied from non-english PoE game clients": "从非英文版游戏客户端复制的任何物品",
  "Any item with a teal highlight has something special about it! Typical reasons are: enchants, fractured, synthesis, identified mods, incursion mods, delve mods, abyss sockets etc. Their price differs and it often requires a manual check.": "任何带有青色高亮的物品都有特别之处！典型原因包括：附魔、裂隙、合成、已鉴定词缀、入侵词缀、深渊词缀、深渊插槽等。它们的价格不同，通常需要手动检查。",
  "Any keepers-filter can be used for Phrecia (although Phrecia likely has a different economy). We intend to release a phrecia-economy version soon after launch.": "任何 keepers-filter 都可用于 Phrecia（尽管 Phrecia 可能有不同的经济）。我们打算在发布后不久发布 phrecia 经济版本。",
