  "Buzzing": "嗡嗡的",
  "By adding e.g. 'GG', all 4-links will need to at least have 2 green colors to get highlighted. You can add one or multiple combinations of 'R', 'G' and 'B'. This is very useful to hide uninteresting linked items.": "例如添加'GG'，所有4连需要至少有2个绿色才能高亮。你可以添加一个或多个'R'、'G'和'B'的组合。这对于隐藏无趣的连缀物品非常有用。",
  "By applying an 'Orb of Chance' on these bases, you have a tiny chance to turn it into valuable unique item.": "在这些基底上使用'机会之球'，你有很小的机会将它变成有价值的 unique 物品。",
  "By default rares have a higher evaluation priority than chromatic recipes. This can be changed here.": "默认情况下，稀有物品具有比幻色配方更高的计算优先级。这可以在这里更改。",
  "By default the filter will hide all (unidentified) corrupted/mirrored rares without an implicit. This of course excludes 6-links and all kind of other exotic items": "默认情况下过滤器会隐藏所有（未鉴定）的腐化/复制稀有物品且没有基底词缀。当然这不包括6连和所有其他特殊物品",
  "By default the filter will hide all (unidentified) corrupted/mirrored rares without an implicit. This of course excludes 6-links and all kinds of other exotic items": "默认情况下，过滤器会隐藏所有没有固定词缀的（未鉴定）腐化/镜像稀有物品。当然不包括六连以及各种特殊物品。",
  "By default, most items look the same, no matter how rare or useful or valuable.": "默认情况下，无论物品多么稀有、实用或值钱，外观看起来都差不多。",
  "By selling a total of 40% quality worth of gems with a specific tag (such as fire) together with a Rune Dagger, Wand, Sceptre or Staff you will be rewarded with a +1 global level to ALL tagged spell gems. This can be great for crafting, ssf or powerful weapons early on": "通过出售带有特定标签的宝石(如火焰)以及符文匕首、法杖、短杖或长杖，你将获得+1该标记的全域等级的法术宝石。这对于制作、ssf或早期强大武器非常有用",
  "By selling a total of 40% quality worth of gems with a specific tag (such as fire) together with a Wand, Sceptre, Rune Dagger or Staff you will be rewarded with a weapon with a +1 GLOBAL level to ALL tagged spell gems. This is a powerful caster weapon early in the endgame.": "出售总品质达40%的特定标签宝石（如火焰）连同魔杖、权杖、符文匕首或长杖，将获得一把所有该标签法术宝石+1全局等级的武器。这是终局前期强力的施法者武器。",
