  "Cluster Jewels": "星团珠宝",
  "Cluster jewels are a huge power source for many builds. Large jewels mostly focus on damage boosts, medium once on utility and small ones on defenses, auras and curses.": "集群珠宝是许多流派的强力来源。大型珠宝多偏向伤害提升，中型偏向功能性，小型偏向防御、光环与诅咒。",
  "Cluster jewels are delirium exclusive drops, that can expand the skilltree in exclusive ways. Itemlevel matters on them. They come in 3 sizes.": "星团珠宝是迷雾专属掉落，能以专属方式扩展技能树。物品等级对它们很重要。它们有 3 种大小。",
