  "Good Melee, Archer and Caster rares (especially weapons) are signalized using the red, green and blue backgrounds and borders while leveling. Note that this is not available on certain styles.": "好的近战、弓手和法师稀有（尤其是武器）在升级时使用红、绿和蓝背景及边框发出信号。请注意，这在某些样式上不可用。",
