  "Idols are only available in 'Phrecia' events as an atlas alternative.": "偶像只在'Phrecia'事件中作为 atlas 替代品可用。",
  "If a base has multiple different uniques. Which price should be used to determine its tier?": "如果一个基底有多个不同的传奇。应该用哪个价格来确定它的分阶？",
  "If an item drops in a level 70 zone, its ItemLevel will be 70, no matter the BaseType or its DropLevel.": "如果一个物品在70级区域掉落，它的物品等级将是70，无视其基底或掉落等级。",
  "If imbued gems can drop, this will catch them (and any other imbued item). Better handling will be added once we know more.": "如果灌注宝石可以掉落，这将捕获它们（以及任何其他灌注物品）。一旦了解更多信息，将添加更好的处理方式。",
  "If you change a color here, it will affect every entry in the filter that uses that color. Items that have the default appearance won't be listed here and can't be changed using the Style Editor.": "在这里修改颜色会影响过滤器中所有使用该颜色的条目。使用默认外观的物品不会列在此处，也无法通过样式编辑器修改。",
