  "In the 3.16 update the base armour value of armour/es/evasion on items can vary by 15%. This value is inherent and can only be changed with a sacred orb. The filter attempts to highlight items with perfect base defense stats for the best crafting results": "在3.16版本的更新中，物品的基础护甲值/闪避值可以变化15%。这个值是固有的，只能用一个崇神石来改变。过滤器试图突出具有完美基础防御属性的物品，以获得最佳制作效果",
  "In the endgame, large RGB items are hidden to maximize efficiency.": "在终局中，大的 RGB 物品被隐藏以最大化效率。",
  "In the first days of new leagues, 5-linked body armors are in fairly high demand. They tend to drop in price rapidly though, as players will gradually switch to using 6-links": "新赛季头几天，五连胸甲需求很高，但价格会迅速下跌，因为玩家会逐渐改用六连。",
