  "Item Progression": "物品进度",
  "Item Progression Editor": "物品进度编辑器",
  "Item progressions highlight the best available class (such as only 1h Axe or Claw) available on your level. Select up to 3 types below and we'll create the progression in just 1 click. The filter also comes with a default item progression. It's less precise than the custom ones, but covers multiple classes.": "物品进度会高亮你当前等级可用的最佳武器类型（如单手斧或爪）。在下方选择最多3种类型，我们将一键创建进度。过滤器也自带默认物品进度，不如自定义的精确，但涵盖多种武器类型。",
