  "itemLevel": "物品等级",
  "ItemLevel >= 75": "ItemLevel >= 75",
  "ItemLevel >= 80": "ItemLevel >= 80",
  "ItemLevel >= 85": "ItemLevel >= 85",
  "ItemLevel 80+ quivers can roll valuable chain corruptions. This rule helps detect these.": "ItemLevel 80+ quivers can roll valuable chain corruptions. This rule helps detect these.",
  "ItemLevel 80+ quivers can roll valuable chain corruptions. This rule helps detecting these.": "物品等级80+的箭袋可以Roll出有价值的连锁腐化词缀。此规则有助于检测这些。",
  "ItemLevel:": "物品等级:",
  "Items can rarely drop uncorrupted with 20-30 quality. These rules look for the right combination of basetype, level and quality.": "物品很少会以未腐化状态掉落20-30品质。这些规则寻找基底类型、等级和品质的正确组合。",
  "Items that have a fractured and veiled mod. It is NOT garantueed that the veiled mod is the fractured one": "具有分裂和隐匿词缀的物品。不保证隐匿词缀就是分裂的那个",
  "Items with 5 linked sockets are useful and valuable early on in the leagues. If they're also 6-socketed, they get the grey recipe background.": "5 连物品在赛季早期有用且有价值。如果它们也是 6 槽的，会得到灰色配方背景。",
  "Items with 6 sockets can be sold at any vendor for 7 Jeweller's Orbs.": "有 6个插槽的物品可以在任何NPC处出售，获得 7个工匠石。",
  "Items with Corrupted Implicits": "具有已腐化词缀的物品",
  "Items with Crucible passive tree": "具有熔炉天赋树的物品",
  "Items without any tag": "没有标签的物品",
  "It's recommended to at least use the threshold of 14. This allows you to get 1 glassblower per 3 mid quality flasks. Note that glassblowers can also be acquired by bying it for 8 whetstones from vendors and drop naturally, so the recipe is not very efficient.": "建议至少使用阈值14。这可令你每用3个中等质量的药剂就能换到1个玻璃弹珠。注意，玻璃弹珠也可以通过使用8个磨刀石头商人那里获得或是自然掉落，所以这个配方不是很有效。",
