  "Notable Drops": "值得注意的掉落",
  "Note that filtering by mods is only possible for EXPLICIT mods of IDENTIFIED items! This excludes any labyrinth enchantments as those are implicit.": "请注意，通过词缀过滤只适用于已鉴定物品！这不包括任何迷宫附魔，因为这些都是隐式的。",
  "Note that spaces and special symbols are not allowed in custom sounds if you want to upload your filter to PoE and that you won't be able to hear this sound in FilterBlade, as we don't have your sound file and can't access your hard drive.": "请注意，如果您想将过滤器上传到PoE，自定义声音名字中不允许出现空格和特殊符号，并且您将无法在FilterBlade中听到此声音，因为我们没有您的声音文件，也无法访问您的硬盘驱动器。",
  "Note that this rule does not detect Echoforge so if you disable Infernal Sword it will still hide that.": "请注意,此规则不会检测回声锻造,因此如果禁用地狱之刃它仍会隐藏",
  "Note that this system is not designed to drop and pricecheck items. It's mostly useful for maps with sextants, corruptions and similar things.": "注意：该系统的设计目的不是掉落并查价，它主要用于带六分仪、腐化等的地图。",
  "Note that you still need to re-export your filter to receive the update, unless you are using the Auto-Updater. We recommend re-exporting once a week to stay up-to-date.": "注意，除非使用自动升级，否则您仍然需要重新导出过滤器以接收更新。我们建议每周重新导出一次，以保持最新状态。",
  "Note: random non-quality skillgems are hidden on higher strictnesses, since they can be purachased from an NPC.": "注意：随机掉落的非品质技能宝石在较高严格度下会被隐藏，因为它们可以从 NPC 处购买。",
  "Note: The section 'hide and highlight rares by type' section can be used to achieve the same result, while also having control over classes and levels.": "注意:“按类型隐藏和突出显示稀有物品”部分可以用于实现相同的结果，同时还可以控制class和级别。",
  "Note: There's sadly NO way to filter these by reward, health percentage etc.": "注意：很遗憾无法通过奖励、生命值百分比等来过滤这些。",
  "Note: There's sadly NO way to filter these by reward, health percentage, rooms etc.": "注意：很遗憾无法通过奖励、生命值百分比、房间等来过滤这些。",
