  "Often very high basetypes, yet very niche in the meta or lower tier meta bases. Not worth picking up later in the league, once you have some decent gear.": "他们的掉落往往很多，但在后期或中后期基底中却非常小众。在联赛后期，一旦你有了一些像样的装备，就不值得再去选择了。",
