  "Path of Exile 1 and 2": "流放之路 1 与 2",
  "Path of Exile lootfilters can't filter contracts by their required heist jobs or reward value!": "流放之路的战利品过滤器不能根据合同需要的夺宝工作或奖励价值来过滤契约！",
  "Path of Exile rewards speed. It's an efficient strategy to save time by picking up just the minimum amount of scrolls, scraps, augments and other low currency. You can even completely stop picking them up. Do note that you can sell transmutation orbs and whetstones for a 1:4 wisdom scroll gain and armorer scraps for 1:2 wisdom scrolls. You can also buy a portal gem to save on portal scrolls. Another efficient technique is to hide low currencies entirely - but with the maximum font size, but show them, while ALT is pressed.": "流放之路奖励速度。这是一种节省时间的有效策略，即只收集最少数量的卷轴、碎片、道具和其他低成本货币。你甚至可以完全不去捡它们。请注意，你可以出售蜕变石和磨刀石来换取1:4的鉴定卷轴收益，也可以出售护甲片来换取1:2的鉴定卷轴收益。你也可以购买传送门宝石以省去传送卷轴。另一种有效的方法是完全隐藏低价通货——但使用最大字体大小，从而在按ALT键时显示它们。",
