  "Selfless Leadership": "无私领导",
  "Selling a 20% gavel together with any map will award you with a Cartographer's Chisel. This recipe is rather low profit and not recommended by most players.": "出售一个 20% 质量的锤子连同任何地图会奖励你一个制图师之凿。这个配方利润相当低，不被大多数玩家推荐。",
  "Selling a 20% quality flask or many flasks with a total of 40% quality will grant you a Glassblower's Bauble. This recipe can be quite useful at the beginning of a new league.": "出售一个 20% 质量的药水或多个总质量为 40% 的药水会给你一个玻璃匠的珠子。这个配方在新赛季开始时非常有用。",
  "Selling a total of 60 Breach Rings together to a vendor will reward you with the Grasping Mail rare item. This item can feature exclusive modifiers, such as the +50% to all defenses. Note that rerolling that item will not allow for new breach modifier to spawn. This rare can be very valuable for crafting.": "将总共60枚裂隙戒指卖给商人将奖励你稀有物品扼杀链甲。这个物品可以有专属的修正，比如全局防御+50%。请注意，重roll该物品将不允许产生新的裂隙修正。这种稀有物品对于制作来说非常有价值。",
  "Selling a total of 60 Unique Rings together to a vendor will reward you with the Loreweave Unique body armour.": "将总共60枚传奇戒指卖给商人，你将获得传奇护甲满溢之甲。",
