  "Sin Trek": "敏锐思维",
  "Since PoE 3.16, the base value for defences on all gear pieces can roll. Meaning the same base can have varying Armour values. Perfection is used to see how good the roll is on a scale from 1 to 100.": "自PoE 3.16以来,所有装备的基础防御值都可以浮动。这意味着相同的基础可以有不同的护甲值。完美度用于衡量浮动的好坏,范围从1到100",
  "Since these gems can only be created by using the Divine Font at the end of the Eternal Labyrinth and can't drop naturally in the world, there is no need for any special filtering or highlight.": "由于这些觉醒宝石只能在永恒迷宫的尽头使用神圣之泉创造，且不会在世界中自然掉落，因此无需任何特殊的过滤或高亮显示。",
