  "Somatic Wand": "肉体法杖",
  "Some BaseTypes have both: very valuable uniques AND cheap ones. The filter can't say which one dropped. These multi-base uniques get more highlight, but play the low-tier unique sound.": "某些基底类型同时具有：非常贵重的暗金和便宜的暗金。过滤器无法判断掉落的是哪一种。这些多基底暗金获得更多高亮，但播放低阶暗金声音。",
  "Some BaseTypes have both: very valuable uniques AND cheap uniques. The filter can't say which one dropped. These multi-base uniques get more highlight, but play the low-tier unique sound.": "一些基底同时存在非常有价值的传奇和廉价的传奇。过滤器不知道是哪个掉了。这些基底共用传奇得到更多的突出，但发出低级别传奇的声音。",
  "Some builds choose to run jewels with more nodes instead of smaller ones, to maximize the stat boosts. This is typical for minion and reservation jewels.": "有些流派会选择节点更多的珠宝而非小型珠宝，以最大化属性加成，常见于召唤与保留类珠宝。",
  "Some item classes like 'Jewels' are completely covered through the class-based filtering below and don't need representing through the matrix.": "某些类别（例如「珠宝」）已完全由下方的类别过滤覆盖，无需在矩阵中体现。",
  "Some itemclasses like 'amulets' are completely covered through the class-based filtering below and don't need representing through the matrix.": "有些物品类，如“护身符”，完全通过下面基于class的过滤覆盖，不需要通过矩阵表示。",
  "Some itemclasses like 'Jewels' are completely covered through the class-based filtering below and don't need representing through the matrix.": "有些物品类，如“珠宝”，完全通过下面基于class的过滤覆盖，不需要通过矩阵表示。",
  "Some items in the game can only be obtained from limited sources. Such bases can be valuable.": "游戏中有些物品只能从有限来源获得。这样的基底可能很有价值。",
  "Some veiled items, like 'Elreon's Veil' tend to be expensive every league. It should be noted that the natural unveil can be very powerful and is stronger than the crafted version of the mod.": "某些隐匿物品（例如「艾尔雷恩的面纱」）每个赛季都很贵。要注意，天然揭示出的词缀可能非常强，比工艺版本更强。",
  "Something Dark": "黑暗之物",
  "Sometimes highly specific items not covered by the list above can hold high value, such as a 'Crusader Moonstone Ring'. This list is designed to cover this niche. You can also add your requirements here.": "有时上述列表未涵盖的高度特定物品可能具有很高价值，例如'圣战者月光石戒指'。此列表旨在覆盖这一细分领域。你也可以在此处添加自己的需求。",
