  "The Cursed King": "诅咒之王",
  "The Customizer is built fail-save and it's hard to 'break' your filter by using it. You will see warnings if you're about to do something dangerous. There is also additional validation when exporting.": "自定义器设计上就是容错的，正常使用很难把过滤器「弄坏」。进行危险操作时会有警告，导出时还有额外校验。",
  "The customizer is designed to be fail-proof. You don't have to worry about accidentally hiding uniques or 6-links or such.": "定制器的设计是防故障的。您不必担心意外地隐藏传奇或6连等东西。",
