  "The Easy Stroll": "轻松漫步",
  "The economy  sometimes has large meta-shifts! A cheap unique can become very expensive very fast (or vice versa)!": "行情有时会发生剧烈变动！一件便宜的传奇可能迅速变得极贵（反之亦然）！",
