  "The Eternity Shroud": "永恒幽影",
  "The Ethereal": "空灵",
  "The Everlasting": "永世长存",
  "The Explorer": "探险家",
  "The Eye of Terror": "恐怖之眼",
  "The Eye of the Dragon": "龙之眼",
  "The False Hope": "虚假的希望",
  "The Fathomless Depths": "无尽深渊",
  "The Feast": "盛宴",
  "The Felbog Fang": "费伯之牙",
  "The Fiend": "劣魔",
  "The filer analyzes the mods of identified rare gear pieces and highlights expensive combinations. This process doesn't work with influenced gear, implicits and enchantments. It's not perfect and may sometimes pick up check combinations, but the items highlighted this way can sometimes be quite valuable.": "过滤器分析已鉴定稀有装备的词缀并高亮昂贵的组合。此过程不适用于受影响装备、隐含属性和附魔。它不完美，有时可能会拾取检查组合，但以这种方式高亮的物品有时可能相当有价值。",
  "The filter also CAN'T check mod ranges, implicit mods, corruptions, enchantments, unique mods or the mods of unidentified items.": "过滤器也「无法」检查词缀数值范围、固定词缀、腐化、附魔、传奇词缀，以及未鉴定物品的词缀。",
  "The filter can't disintinguish between expensive and cheap unique jewels. All of them are treated the same way!": "过滤器无法区分昂贵和廉价的传奇珠宝。所有都受到同样的待遇！",
  "The filter can't disintinguish between expensive and cheap unique jewels. However, unique uncorrupted jewels have high odds of being very valuable": "过滤器无法区分昂贵与廉价的传奇珠宝。不过，未腐化的传奇珠宝有较大概率非常值钱。",
  "The filter comes with a system to check if an identified rare has interesting stat combos. Identified rares drop rarely, but if NO statcombo was detected, you might consider hiding them. This can be done here.": "过滤器带有一个系统来检查已鉴定稀有物品是否有有趣的属性组合。已鉴定稀有物品掉落稀少，但如果没有检测到属性组合，你可以考虑隐藏它们。可以在此处操作。",
  "The filter has several dozens of rules, such as early jewellery, boots, top basetypes (for a quick essence/transmute-slam) to assist you while leveling. Not every item is going to be useful for everyone and we recommend to customize your filter for the best experience.": "过滤器有几十条规则，例如早期珠宝、靴子、顶级基底（用于快速 essence/transmute-slam）来帮助您升级。并非每个物品对每个人都很有用，我们建议自定义过滤器以获得最佳体验。",
  "The filter highlights map drops of a higher tier than the one you're in with extra highlight (disabled on some styles)": "该过滤器会以额外的高亮显示比你当前所在T级更高的地图掉落（在某些样式中可能已禁用）。",
  "The filter starts hiding magic items at higher levels while leveling, this can be adjusted here": "过滤器在升级时会在更高等级开始隐藏魔法物品，可以在此处调整",
  "The filter will check identified rares for interesting mod combinations and highlight these items. By setting this rule to HIDE all items that have NOT passed the 'interesting identified mods check' will be hidden. This is useful if you're still searching for specific rare combinations, but would like to reduce the number of items visible.": "该过滤将检查已鉴定的稀有物品以寻找有趣的属性组合，并高亮显示这些物品。通过将此规则设置为“隐藏”，所有未通过“有趣已鉴定属性检查”的物品将被隐藏。这在你仍在寻找特定稀有物品组合时非常有用，但希望减少可见物品的数量。",
  "the filter. That's it!": "过滤器。就这么简单！",
