  "Useful currency that drops while leveling. These rules have priority over normal currency rules, but only apply in areas under level 68. Great for new leagues!": "练级时掉落的有用通货。这些规则优先于普通通货规则，但只适用于 68 级以下区域。非常适合新赛季使用！",
