  "When enabled, the item will keep the default sound effect (such as a metallic noise for weapons or a high pitch \"pling\" for orbs). An item can have both the default sound and a filter-alert sound.": "启用时,物品将保留默认音效(如武器的金属声或宝石的尖锐'叮'声)。物品可以同时拥有默认音效和过滤警报音效",
