  "You are Crushed": "你被压碎",
  "You can add an icon for this item on the inGame MiniMap here": "你可以为这个物品添加一个图标以在游戏小地图上显示",
  "You can also add Carnal Armour to this rule to make it detect 2 Abyssal Socket variation of Shroud of the Lightless": "你也可以在此规则中添加 Carnal Armour 来检测 Shroud of the Lightless 的两个深渊插槽变体",
  "You can also view": "你也可以查看",
  "You can also view other player's filters on their": "你也可以查看其他玩家的过滤器于",
  "You can change all of these settings in the customizer screen here. To quickly jump to the settings for a certain item, right click the item label or CTRL+click the item.": "你可以在自定义器页面修改所有这些设置。想快速跳到某个物品的设置，右键点击物品标签，或按住 CTRL 点击物品。",
  "You can come back later to fine-tune when you notice things that you'd like to change!": "之后你发现想改的地方，随时可以回来微调！",
  "You can customize them to fit to your character and style!": "你可以按自己的角色和喜好进行定制！",
  "You can detect other items that have both Shaper and Elder influences in this rule by adding their basetypes:": "你可以通过添加它们的基础类型在此规则中检测其他同时具有塑者和长老影响的物品:",
  "You can detect other items that have either of Shaper or Elder influences in this rule by adding their basetypes:": "你可以通过添加它们的基础类型在此规则中检测其他具有塑者或长老影响的物品:",
  "You can detect other socketless uniques in this rule by adding their basetypes:": "你可以通过在此规则中添加它们的基底类型来检测其他无插槽的稀有物品：",
  "You can detect other Synthesised uniques in this rule or in Rational Doctrine rule by adding their basetypes:": "你可以通过添加它们的基础类型在此规则或理性教条规则中检测其他合成暗金:",
  "You can download it as backUp or to move it between the beta and live version of FilterBlade.": "你可以下载它作为备份，或在 FilterBlade 测试版与正式版之间迁移。",
  "You can find gold all throughout the game. It's picked up automatically as you walk over it.": "你可以在整个游戏中找到金币。走过时会自动拾取。",
  "You can find more quality flasks rules in the 'Endgame -> Flasks' and 'Campaign -> Flasks' sections.": "你可以在终局 -> 药剂和战役 -> 药剂章节中找到更多高品质药剂规则。",
  "You can have a light Beam displayed on top of the item in the game world. Pick color and duration here!": "你可以令游戏世界里掉落的物品上方显示光束。在这里选择颜色和持续时间!",
  "You can right-click e.g. an item to jump to its rule in the Customizer or a tierlist element to move it! (Long press on mobile)": "右键点击某个物品，可直接跳到它在自定义器中的规则；右键点击分级表元素可以移动它！（移动端长按）",
  "You can see your synced filters on your": "你可以查看你同步的过滤器于",
  "You can specify multiple requirements, each with the total number of sockets as well as the amount of each color.": "你可以指定多个要求,每个要求有插槽总数以及每种颜色的数量",
  "You CAN test the uploaded filters in the loot simulator": "你可以在掉落模拟器中测试上传的过滤器",
  "You can then also always paste it directly into the search bar at the top!": "之后你随时可以把它直接粘贴到顶部搜索栏！",
  "You can then use these modules on the": "之后你可以在",
  "You CAN use the advanced->structure screen to change the filter": "你可以用「高级 → 结构」页面修改过滤器",
  "You can use the 'Stacked Tiering Mode' above to automate behaviour for stacked item drops!": "你可以使用上方的「堆叠分阶模式」自动处理堆叠掉落！",
  "You get a cartographer's chisel by vendoring a 20% quality Gavel, Rock Breaker, or Stone Hammer together with any map. This recipe is considered too slow for most purposes and it's not recommendend": "你可以通过出售20%品质的坚锤、破岩锤或石锤和一张任意地图来获得制图钉。对于大多数目的来说，这个配方被认为太慢了，不建议使用",
  "You take 10% of Damage from Blocked Hits": "你受到格挡命中的 10% 伤害",
  "Your changes and 'Locks' have priority over these updates. Meaning any item you have put into a different tier will stay there and won't be moved by these updates.": "您的更改和“锁定”优先于这些更新。这意味着你放到不同阶级的任何物品都将留在那里，不会被这些更新所移动。",
  "Your Hits treat Cold Resistance as 10% higher than actual value": "你的击中把冰霜抗性视为比实际高 10%",
  "your synced filters": "你同步过的过滤器",
  "You're done customizing and want to save and download/sync the current filter? Click here!": "你已经完成了自定义并希望保存和下载/同步当前过滤器?点击这里!",
  "You're done? Head to the": "弄好了？前往",
